type referenceCase struct {
	name       string
	base       []float64
	head       []float64
	baseMedian float64
	headMedian float64
	baseMean   float64
	headMean   float64
	baseStddev float64
	headStddev float64
	baseCV     float64
	headCV     float64
	deltaPct   float64
	uStatistic float64
	pValue     float64
}

func almostEqual(a, b, tol float64) bool {
	return math.Abs(a-b) <= tol
}

