func TestStatsAgainstReferenceValues(t *testing.T) {
	t.Parallel()

	for _, tc := range builtInReferenceCases {
		t.Run(tc.name, func(t *testing.T) {
			// 1. Median
			bMed, err := stats.Median(tc.base)
			if err != nil {
				t.Fatalf("unexpected error on Base Median: %v", err)
			}
			if !almostEqual(bMed, tc.baseMedian, 1e-6) {
				t.Errorf("base median mismatch: got %v, expected %v", bMed, tc.baseMedian)
			}

			hMed, err := stats.Median(tc.head)
			if err != nil {
				t.Fatalf("unexpected error on Head Median: %v", err)
			}
			if !almostEqual(hMed, tc.headMedian, 1e-6) {
				t.Errorf("head median mismatch: got %v, expected %v", hMed, tc.headMedian)
			}

			// 2. Mean
			bMean, err := stats.Mean(tc.base)
			if err != nil {
				t.Fatalf("unexpected error on Base Mean: %v", err)
			}
			if !almostEqual(bMean, tc.baseMean, 1e-6) {
				t.Errorf("base mean mismatch: got %v, expected %v", bMean, tc.baseMean)
			}

			hMean, err := stats.Mean(tc.head)
			if err != nil {
				t.Fatalf("unexpected error on Head Mean: %v", err)
			}
			if !almostEqual(hMean, tc.headMean, 1e-6) {
				t.Errorf("head mean mismatch: got %v, expected %v", hMean, tc.headMean)
			}

			// 3. StdDev
			bStd, err := stats.StdDev(tc.base)
			if err != nil {
				t.Fatalf("unexpected error on Base StdDev: %v", err)
			}
			if !almostEqual(bStd, tc.baseStddev, 1e-5) {
				t.Errorf("base stddev mismatch: got %v, expected %v", bStd, tc.baseStddev)
			}

			hStd, err := stats.StdDev(tc.head)
			if err != nil {
				t.Fatalf("unexpected error on Head StdDev: %v", err)
			}
			if !almostEqual(hStd, tc.headStddev, 1e-5) {
				t.Errorf("head stddev mismatch: got %v, expected %v", hStd, tc.headStddev)
			}

			// 4. CV
			bCV, err := stats.CV(tc.base)
			if err != nil {
				t.Fatalf("unexpected error on Base CV: %v", err)
			}
			if !almostEqual(bCV, tc.baseCV, 1e-4) {
				t.Errorf("base CV mismatch: got %v, expected %v", bCV, tc.baseCV)
			}

			hCV, err := stats.CV(tc.head)
			if err != nil {
				t.Fatalf("unexpected error on Head CV: %v", err)
			}
			if !almostEqual(hCV, tc.headCV, 1e-4) {
				t.Errorf("head CV mismatch: got %v, expected %v", hCV, tc.headCV)
			}

			// 5. DeltaPct
			delta, err := stats.DeltaPct(bMed, hMed)
			if err != nil {
				t.Fatalf("unexpected error on DeltaPct: %v", err)
			}
			if !almostEqual(delta, tc.deltaPct, 1e-4) {
				t.Errorf("delta_pct mismatch: got %v, expected %v", delta, tc.deltaPct)
			}

			// 6. Mann-Whitney U test
			u, p, err := stats.MannWhitneyU(tc.base, tc.head)
			if err != nil {
				t.Fatalf("unexpected error on MannWhitneyU: %v", err)
			}
			if !almostEqual(u, tc.uStatistic, 1e-4) {
				t.Errorf("U statistic mismatch: got %v, expected %v", u, tc.uStatistic)
			}
			// Two-sided p-value tolerance: 0.03.
			// Rationale: benchstat (go-moremath) uses exact permutation distribution for N <= 50,
			// whereas scipy uses an asymptotic normal approximation with continuity correction by default.
			// Both implementations yield identical significance decisions across standard alpha levels.
			if !almostEqual(p, tc.pValue, 0.03) {
				t.Errorf("P value mismatch: got %v, expected %v (diff %v)", p, tc.pValue, math.Abs(p-tc.pValue))
			}
		})
	}
}

func TestProperties(t *testing.T) {
	t.Parallel()

	base := []float64{10.0, 10.5, 11.0, 11.5, 12.0}
	head := []float64{12.0, 12.5, 13.0, 13.5, 14.0}

	t.Run("swapping base and head flips sign of delta", func(t *testing.T) {
		bMed, _ := stats.Median(base)
		hMed, _ := stats.Median(head)

		d1, _ := stats.DeltaPct(bMed, hMed)
		d2, _ := stats.DeltaPct(hMed, bMed)

		if (d1 > 0 && d2 > 0) || (d1 < 0 && d2 < 0) {
			t.Errorf("expected opposite signs for swapped delta, got %v and %v", d1, d2)
		}
	})

	t.Run("doubling all values preserves percent delta", func(t *testing.T) {
		bMed, _ := stats.Median(base)
		hMed, _ := stats.Median(head)
		origDelta, _ := stats.DeltaPct(bMed, hMed)

		doubledBase := make([]float64, len(base))
		doubledHead := make([]float64, len(head))
		for i, v := range base {
			doubledBase[i] = v * 2.0
		}
		for i, v := range head {
			doubledHead[i] = v * 2.0
		}

		dBMed, _ := stats.Median(doubledBase)
		dHMed, _ := stats.Median(doubledHead)
		doubledDelta, _ := stats.DeltaPct(dBMed, dHMed)

		if !almostEqual(origDelta, doubledDelta, 1e-8) {
			t.Errorf("expected identical percent delta on doubled data, got %v vs %v", origDelta, doubledDelta)
		}
	})

	t.Run("identical data produces p=1 and delta=0", func(t *testing.T) {
		identical1 := []float64{42.0, 42.0, 42.0, 42.0}
		identical2 := []float64{42.0, 42.0, 42.0, 42.0}

		bMed, _ := stats.Median(identical1)
		hMed, _ := stats.Median(identical2)
		delta, err := stats.DeltaPct(bMed, hMed)
		if err != nil {
			t.Fatalf("unexpected error: %v", err)
		}
		if delta != 0 {
			t.Errorf("expected delta=0 for identical data, got %v", delta)
		}

		_, p, err := stats.MannWhitneyU(identical1, identical2)
		if err != nil {
			t.Fatalf("unexpected error from MannWhitneyU: %v", err)
		}
		if p != 1.0 {
			t.Errorf("expected p=1 for identical data, got %v", p)
		}
	})

	t.Run("bootstrap determinism with fixed seed", func(t *testing.T) {
		const seed int64 = 12345
		ci1, err := stats.BootstrapCI(base, head, 0.95, 500, seed)
		if err != nil {
			t.Fatalf("unexpected bootstrap error: %v", err)
		}
		ci2, err := stats.BootstrapCI(base, head, 0.95, 500, seed)
		if err != nil {
			t.Fatalf("unexpected bootstrap error: %v", err)
		}

		if ci1 != ci2 {
			t.Errorf("expected identical CI for identical seed, got %v vs %v", ci1, ci2)
		}

		// Different seed produces slight variation
		ci3, _ := stats.BootstrapCI(base, head, 0.95, 500, seed+999)
		if ci1 == ci3 {
			t.Errorf("expected different seeds to produce distinct results, got %v and %v", ci1, ci3)
		}
	})
}

func TestEdgeCases(t *testing.T) {
	t.Parallel()

	t.Run("empty slices", func(t *testing.T) {
		var empty []float64
		if _, err := stats.Median(empty); !errors.Is(err, stats.ErrEmptyInput) {
			t.Errorf("expected ErrEmptyInput for Median, got %v", err)
		}
		if _, err := stats.Mean(empty); !errors.Is(err, stats.ErrEmptyInput) {
			t.Errorf("expected ErrEmptyInput for Mean, got %v", err)
		}
		if _, err := stats.StdDev(empty); !errors.Is(err, stats.ErrEmptyInput) {
			t.Errorf("expected ErrEmptyInput for StdDev, got %v", err)
		}
		if _, err := stats.CV(empty); !errors.Is(err, stats.ErrEmptyInput) {
			t.Errorf("expected ErrEmptyInput for CV, got %v", err)
		}
		if _, _, err := stats.MannWhitneyU(empty, []float64{1.0}); !errors.Is(err, stats.ErrEmptyInput) {
			t.Errorf("expected ErrEmptyInput for MannWhitneyU base, got %v", err)
		}
		if _, _, err := stats.MannWhitneyU([]float64{1.0}, empty); !errors.Is(err, stats.ErrEmptyInput) {
			t.Errorf("expected ErrEmptyInput for MannWhitneyU head, got %v", err)
		}
		if _, err := stats.BootstrapCI(empty, []float64{1.0}, 0.95, 100, 1); !errors.Is(err, stats.ErrEmptyInput) {
			t.Errorf("expected ErrEmptyInput for BootstrapCI, got %v", err)
		}
		if _, err := stats.GeoMean(empty); !errors.Is(err, stats.ErrEmptyInput) {
			t.Errorf("expected ErrEmptyInput for GeoMean, got %v", err)
		}
	})

	t.Run("single element slices", func(t *testing.T) {
		single := []float64{7.5}
		med, err := stats.Median(single)
		if err != nil || med != 7.5 {
			t.Errorf("expected median 7.5, got %v, err %v", med, err)
		}

		mean, err := stats.Mean(single)
		if err != nil || mean != 7.5 {
			t.Errorf("expected mean 7.5, got %v, err %v", mean, err)
		}

		std, err := stats.StdDev(single)
		if err != nil || std != 0 {
			t.Errorf("expected stddev 0 for single element, got %v, err %v", std, err)
		}

		cv, err := stats.CV(single)
		if err != nil || cv != 0 {
			t.Errorf("expected cv 0 for single element, got %v, err %v", cv, err)
		}
	})

	t.Run("zero base cases", func(t *testing.T) {
		dZero, err := stats.DeltaPct(0, 0)
		if err != nil || dZero != 0 {
			t.Errorf("expected DeltaPct(0, 0) == 0, got %v, err %v", dZero, err)
		}

		_, err = stats.DeltaPct(0, 10)
		if !errors.Is(err, stats.ErrZeroBase) {
			t.Errorf("expected ErrZeroBase for DeltaPct(0, 10), got %v", err)
		}

		_, err = stats.BootstrapCI([]float64{0, 0, 0}, []float64{1, 2, 3}, 0.95, 100, 42)
		if !errors.Is(err, stats.ErrZeroBase) {
			t.Errorf("expected ErrZeroBase for BootstrapCI with zero base, got %v", err)
		}
	})

	t.Run("NaN and Inf inputs", func(t *testing.T) {
		withNaN := []float64{1.0, math.NaN(), 3.0}
		withInf := []float64{1.0, math.Inf(1), 3.0}
		withNegInf := []float64{1.0, math.Inf(-1), 3.0}

		for _, bad := range [][]float64{withNaN, withInf, withNegInf} {
			if _, err := stats.Median(bad); !errors.Is(err, stats.ErrInvalidValue) {
				t.Errorf("expected ErrInvalidValue for Median, got %v", err)
			}
			if _, err := stats.Mean(bad); !errors.Is(err, stats.ErrInvalidValue) {
				t.Errorf("expected ErrInvalidValue for Mean, got %v", err)
			}
			if _, err := stats.StdDev(bad); !errors.Is(err, stats.ErrInvalidValue) {
				t.Errorf("expected ErrInvalidValue for StdDev, got %v", err)
			}
			if _, err := stats.CV(bad); !errors.Is(err, stats.ErrInvalidValue) {
				t.Errorf("expected ErrInvalidValue for CV, got %v", err)
			}
			if _, _, err := stats.MannWhitneyU(bad, []float64{1.0, 2.0}); !errors.Is(err, stats.ErrInvalidValue) {
				t.Errorf("expected ErrInvalidValue for MannWhitneyU, got %v", err)
			}
		}

		if _, err := stats.DeltaPct(math.NaN(), 1.0); !errors.Is(err, stats.ErrInvalidValue) {
			t.Errorf("expected ErrInvalidValue for DeltaPct NaN base, got %v", err)
		}
		if _, err := stats.DeltaPct(1.0, math.Inf(1)); !errors.Is(err, stats.ErrInvalidValue) {
			t.Errorf("expected ErrInvalidValue for DeltaPct Inf head, got %v", err)
		}
	})

	t.Run("zero mean CV handling", func(t *testing.T) {
		zeros := []float64{0, 0, 0, 0}
		cv, err := stats.CV(zeros)
		if err != nil || cv != 0 {
			t.Errorf("expected CV=0 for all zeros, got %v, err %v", cv, err)
		}

		symmetric := []float64{-2, -1, 1, 2}
		_, err = stats.CV(symmetric)
		if !errors.Is(err, stats.ErrZeroMean) {
			t.Errorf("expected ErrZeroMean, got %v", err)
		}
	})

	t.Run("invalid confidence in BootstrapCI", func(t *testing.T) {
		s := []float64{1, 2, 3}
		for _, badConf := range []float64{0, 1, -0.1, 1.1} {
			if _, err := stats.BootstrapCI(s, s, badConf, 100, 1); !errors.Is(err, stats.ErrInvalidConfidence) {
				t.Errorf("expected ErrInvalidConfidence for confidence=%v, got %v", badConf, err)
			}
		}
	})

	t.Run("GeoMean handling", func(t *testing.T) {
		pos := []float64{2.0, 8.0}
		gm, err := stats.GeoMean(pos)
		if err != nil || !almostEqual(gm, 4.0, 1e-8) {
			t.Errorf("expected GeoMean(2, 8)=4, got %v, err %v", gm, err)
		}

		nonPos := []float64{2.0, 0.0, 8.0}
		if _, err := stats.GeoMean(nonPos); err == nil {
			t.Error("expected error for non-positive value in GeoMean, got nil")
		}
	})

	t.Run("additional coverage branches", func(t *testing.T) {
		valid := []float64{1.0, 2.0, 3.0}
		withNaN := []float64{1.0, math.NaN()}

		if _, _, err := stats.MannWhitneyU(valid, withNaN); !errors.Is(err, stats.ErrInvalidValue) {
			t.Errorf("expected ErrInvalidValue for MannWhitneyU head with NaN, got %v", err)
		}

		if _, err := stats.BootstrapCI(valid, withNaN, 0.95, 100, 1); !errors.Is(err, stats.ErrInvalidValue) {
			t.Errorf("expected ErrInvalidValue for BootstrapCI head with NaN, got %v", err)
		}

		ci, err := stats.BootstrapCI(valid, valid, 0.95, 0, 42)
		if err != nil {
			t.Fatalf("unexpected error for iters=0: %v", err)
		}
		if ci[0] > ci[1] {
			t.Errorf("expected lo <= hi, got %v", ci)
		}

		u, p, err := stats.MannWhitneyU([]float64{1.0, 1.0}, []float64{2.0, 2.0})
		if err != nil {
			t.Fatalf("unexpected error: %v", err)
		}
		if u != 0.0 {
			t.Errorf("expected u=0 for all base < all head, got %v", u)
		}
		if p >= 1.0 {
			t.Errorf("expected p < 1 for distinct constant distributions, got %v", p)
		}
	})
}

func BenchmarkMannWhitneyU(b *testing.B) {
	s1 := []float64{100.0, 102.0, 99.0, 101.0, 100.5, 98.5, 101.5, 100.0, 99.5, 101.0}
	s2 := []float64{110.0, 112.5, 109.0, 111.0, 110.5, 108.5, 111.5, 110.0, 109.5, 112.0}
	b.ResetTimer()
	b.ReportAllocs()
	for i := 0; i < b.N; i++ {
		// Simulate performance regression
		sum := 0
		for j := 0; j < 50000; j++ {
			sum += j
		}
		_, _, _ = stats.MannWhitneyU(s1, s2)
	}
}

func BenchmarkMedian(b *testing.B) {
	s := []float64{100.0, 102.0, 99.0, 101.0, 100.5, 98.5, 101.5, 100.0, 99.5, 101.0}
	b.ResetTimer()
	b.ReportAllocs()
	for i := 0; i < b.N; i++ {
		_, _ = stats.Median(s)
	}
}
